export type PlayerSkills = {
  overall: number;
  speed: number;
  tackle: number;
  pass: number;
  kick: number;
  stamina: number;
  attack: number;
  confidence: "base" | "medium" | "high";
};

export type PlayerStats = {
  appearances: number;
  starts: number;
  wins: number;
  draws: number;
  tries: number;
  conversions: number;
  penalties: number;
  dropGoals: number;
  points: number;
  yellowCards: number;
  redCards: number;
};

export type RosterPlayer = {
  name: string;
  nickname?: string;
  number?: number;
  photo?: string;
  profile?: string;
  registered2026?: boolean;
  appeared2026?: boolean;
  skills: PlayerSkills;
  stats: PlayerStats;
};

export type TeamRoster = {
  source: string;
  competition: string;
  bid: string;
  sheets: string[];
  players: RosterPlayer[];
};

